        xhr.open(...params);
        setXhrHeaders(formio, xhr);
      };
      Promise.resolve(xhrCallback(xhr, serverResponse, abortCallback)).then((payload) => {
        // if payload is nullish we can assume the provider took care of the entire upload process
        if (!payload) {
