  static get builderInfo() {
    return {
      title: 'Data Map',
      icon: 'th-list',
      group: 'data',
      documentation: '/userguide/form-building/data-components#data-map',
      showPreview: false,
      weight: 20,
      schema: DataMapComponent.schema()
