  /**
   * Load the subform.
   * @param {boolean} fromAttach - This function is being called from an `attach` method.
   * @returns {Promise} - The promise that resolves when the subform is loaded.
   */
  loadSubForm(fromAttach) {
    if (this.builderMode || this.isHidden() || (this.isSubFormLazyLoad() && !fromAttach)) {
      return Promise.resolve();
    }

    if (this.hasLoadedForm && !this.isRevisionChanged &&
      !(this.options.pdf && this.component?.useOriginalRevision && _.isNull(this.subForm) && !this.subFormLoading)
    ) {
      // Pass config down to sub forms.
      if (this.root && this.root.form && this.root.form.config && !this.formObj.config) {
        this.formObj.config = this.root.form.config;
      }
      return Promise.resolve(this.formObj);
    }
    else if (this.formSrc) {
      this.subFormLoading = true;
      const options = this.root?.formio?.base && this.root?.formio?.projectUrl
        ? {
            base: this.root.formio.base,
            project: this.root.formio.projectUrl,
          }
        : {};
      return (new Formio(this.formSrc, options)).loadForm({ params: { live: 1 } })
        .then((formObj) => {
          this.formObj = formObj;
          if (this.options.pdf && this.component.useOriginalRevision) {
            this.formObj.display = 'form';
          }
          this.subFormLoading = false;
          return formObj;
        })
        .catch((err) => {
          console.log(err);
          return null;
        });
    }
    return Promise.resolve();
  }

  get subFormData() {
    return this.dataValue?.data || {};
  }

  checkComponentValidity(data, dirty, row, options, errors = []) {
    options = options || {};
    const silentCheck = options.silentCheck || false;

    if (this.subForm && !this.isNestedWizard) {
      return this.subForm.checkValidity(this.subFormData, dirty, null, silentCheck, errors);
    }

    return super.checkComponentValidity(data, dirty, row, options, errors);
  }

  checkComponentConditions(data, flags, row) {
    const visible = super.checkComponentConditions(data, flags, row);

    // Return if already hidden
    if (!visible) {
      return visible;
    }

    if (this.subForm) {
      return this.subForm.checkConditions(this.subFormData);
    }
    // There are few cases when subForm is not loaded when a change is triggered,
    // so we need to perform checkConditions after it is ready, or some conditional fields might be hidden in View mode
    else if (this.subFormReady) {
      this.subFormReady.then(() => {
        if (this.subForm) {
          return this.subForm.checkConditions(this.subFormData);
        }
      });
    }

    return visible;
  }

  calculateValue(data, flags, row) {
    if (this.subForm) {
      return this.subForm.calculateValue(this.subFormData, flags);
    }

    return super.calculateValue(data, flags, row);
  }

  setPristine(pristine) {
    super.setPristine(pristine);
    if (this.subForm) {
      this.subForm.setPristine(pristine);
    }
  }

  /**
   * Determine if the subform should be submitted.
   * @returns {*|boolean} - TRUE if the subform should be submitted, FALSE if it should not.
   */
  get shouldSubmit() {
    return this.subFormReady && (!this.component.hasOwnProperty('reference') || this.component.reference) && !this.isHidden();
  }

  /**
   * Returns the data for the subform.
   * @returns {*} - the data for the subform.
   */
  getSubFormData() {
    if (_.get(this.subForm, 'form.display') === 'pdf') {
      return this.subForm.getSubmission();
    }
    else {
      return Promise.resolve(this.dataValue);
    }
  }

  /**
   * Submit the subform if configured to do so.
   * @returns {Promise} - The promise that resolves when the subform is submitted.
   */
  submitSubForm() {
    // If we wish to submit the form on next page, then do that here.
    if (this.shouldSubmit) {
      return this.subFormReady.then(() => {
        if (!this.subForm) {
          return this.dataValue;
        }
        this.subForm.nosubmit = false;
        this.subForm.submitted = true;
        return this.subForm.submitForm().then(result => {
          this.subForm.loading = false;
          this.subForm.showAllErrors = false;
          this.dataValue = result.submission;
          return this.dataValue;
        }).catch(err => {
          this.subForm.showAllErrors = true;
          this.subForm.onSubmissionError(err);
          return Promise.reject(err);
        });
      });
    }
    return this.getSubFormData();
  }

  /**
   * Submit the form before the next page is triggered.
   * @param {Function} next - The function to trigger the next page.
   * @returns {Promise} - The promise that resolves when the subform submission is complete (if necessary) and the next page is triggered.
   */
  beforePage(next) {
    // Should not submit child forms if we are going to the previous page
    if (!next) {
      return super.beforePage(next);
    }
    return this.submitSubForm(true).then(() => super.beforePage(next));
  }

  /**
   * Submit the form before the whole form is triggered.
   * @returns {Promise} - The promise that resolves when the subform submission is complete (if necessary) and the form is submitted.
   */
  beforeSubmit() {
    const submission = this.dataValue;
    // Cancel triggered saveDraft
    if (this.subForm?.draftEnabled && this.subForm.triggerSaveDraft?.cancel) {
      this.subForm.triggerSaveDraft.cancel();
    }

    const isAlreadySubmitted = submission && submission._id && submission.form;
    const isDraftSubmission = this.options.saveDraft && submission.state === 'draft';

    // This submission has already been submitted, so just return the reference data.
    if (isAlreadySubmitted && !this.subForm?.wizard && !isDraftSubmission) {
      this.dataValue = submission;
      return Promise.resolve(this.dataValue);
    }
    return this.submitSubForm(false)
      .then(() => {
        return this.dataValue;
      })
      .then(() => super.beforeSubmit());
  }

  isSubFormLazyLoad() {
    return  this.root?._form?.display === 'wizard' && this.component.lazyLoad;
  }

  isHidden() {
    if (!this.visible) {
      return true;
    }

    return !super.checkConditions(this.rootValue);
  }

  setValue(submission, flags = {}) {
    const changed = super.setValue(submission, flags);
    this.valueChanged = true;
    if (this.subForm) {
      const revisionPath = submission._frid ? '_frid' : '_vid';
      const shouldLoadOriginalRevision = this.useOriginalRevision
      && (_.isNumber(submission[revisionPath]) || _.isNumber(submission._fvid))
      && _.isNumber(this.subForm.form?.[revisionPath])
      && submission._fvid !== this.subForm.form[revisionPath];

      if (shouldLoadOriginalRevision) {
        this.setFormRevision( submission._frid || submission._fvid);
        this.createSubForm().then(() => {
          this.attach(this.element);
        });
      }
      else {
        this.setSubFormValue(submission, flags);
      }
    }
    return changed;
  }

  setSubFormValue(submission, flags) {
    const shouldLoadSubmissionById = submission
      && submission._id
      && this.subForm.formio
      && _.isEmpty(submission.data);
    const shouldLoadDraftById = this.options.saveDraft && _.isEmpty(submission.data) && _.get(this.subForm, 'submission._id');

    if (shouldLoadSubmissionById || shouldLoadDraftById) {
      const formId = submission.form || this.formObj.form || this.component.form;
      const submissionUrl = `${this.subForm.formio.formsUrl}/${formId}/submission/${submission._id || this.subForm.submission._id}`;
      const options = this.root?.formio?.base && this.root?.formio?.projectUrl
      ? {
          base: this.root.formio.base,
          project: this.root.formio.projectUrl,
        }
      : {};
      this.subForm.setUrl(submissionUrl, { ...this.options, ...options });
      this.subForm.loadSubmission().catch((err) => {
        console.error(`Unable to load subform submission ${submission._id}:`, err);
      });
    }
    else {
      this.onSetSubFormValue(submission, flags);
    }
  }
  /**
   * Sets the subform value
   * @param {object|null|undefined} submission - The submission to set.
   * @param {object|null|undefined} flags - Any flags to apply when setting the submission.
   * @returns {void}
   */
  onSetSubFormValue(submission, flags) {
    this.subForm.setValue(submission, flags);
  }

  isEmpty(value = this.dataValue) {
    return value === null || _.isEqual(value, this.emptyValue) || (this.areAllComponentsEmpty(value?.data) && !value?._id);
  }

  areAllComponentsEmpty(data) {
    let res = true;
    if (this.subForm) {
      this.subForm.everyComponent((comp) => {
        const componentValue = _.get(data, comp.key);
        res &= comp.isEmpty(componentValue);
      });
    }
    else {
      res = false;
    }
    return res;
  }

  getValue() {
    if (this.subForm) {
      return this.subForm.getValue();
    }
    return this.dataValue;
  }

  get errors() {
    let errors = super.errors;
    if (this.subForm) {
      errors = errors.concat(this.subForm.errors);
    }
    return errors;
  }

  updateSubFormVisibility() {
    if (this.subForm) {
      this.subForm.parentVisible = this.visible;
    }
  }

  /**
   * Determines if this form is a Nested Wizard
   * which means it should be a Wizard itself and should be a direct child of a Wizard's page
   * @returns {boolean} - TRUE if this form is a Nested Wizard, FALSE otherwise
   */
  get isNestedWizard() {
    return this.subForm?._form?.display === 'wizard' && this.parent?.parent?._form?.display === 'wizard';
  }

  get visible() {
    return super.visible;
  }

  set visible(value) {
    const isNestedWizard = this.isNestedWizard;

    if (this._visible !== value) {
      this._visible = value;
      // Form doesn't load if hidden. If it becomes visible, create the form.
      if (!this.subForm && value) {
        this.createSubForm();
        this.subFormReady.then(() => {
          this.updateSubFormVisibility();
          this.clearOnHide();
        });
        this.redraw();
        return;
      }
      this.updateSubFormVisibility();
      this.clearOnHide();
      isNestedWizard ? this.rebuild() : this.redraw();
    }
    if (!value && isNestedWizard) {
      this.root.redraw();
    }
  }

  get parentVisible() {
    return super.parentVisible;
  }

  set parentVisible(value) {
    if (this._parentVisible !== value) {
      this._parentVisible = value;
      this.clearOnHide();
      // Form doesn't load if hidden. If it becomes visible, create the form.
      if (!this.subForm && value) {
        this.createSubForm();
        this.subFormReady.then(() => {
          this.updateSubFormVisibility();
        });
        this.redraw();
        return;
      }
      this.updateSubFormVisibility();
      this.redraw();
    }
  }

  isInternalEvent(event) {
    switch (event) {
      case 'focus':
      case 'blur':
      case 'componentChange':
      case 'componentError':
      case 'error':
      case 'formLoad':
      case 'languageChanged':
      case 'render':
      case 'checkValidity':
      case 'initialized':
      case 'submit':
      case 'submitButton':
      case 'nosubmit':
      case 'updateComponent':
      case 'submitDone':
      case 'submissionDeleted':
      case 'requestDone':
      case 'nextPage':
      case 'prevPage':
      case 'wizardNavigationClicked':
      case 'updateWizardNav':
      case 'restoreDraft':
      case 'saveDraft':
      case 'saveComponent':
      case 'pdfUploaded':
        return true;
      default:
        return false;
    }
  }

  createEmitter() {
    const emitter = new EventEmitter();
    const nativeEmit = emitter.emit;
    const that = this;
    emitter.emit = function(event, ...args) {
      const eventType = event.replace(`${that.options.namespace}.`, '');
      nativeEmit.call(this, event, ...args);
      if (!that.isInternalEvent(eventType)) {
        that.emit(eventType, ...args);
      }
    };

    return emitter;
  }

  deleteValue() {
    super.setValue(null, {
      noUpdateEvent: true,
      noDefault: true
    });
    this.unset();
  }
}

import Element from './Element';
import { Formio } from './Formio';
import Displays from './displays';
import templates from './templates';
import * as FormioUtils from './utils/utils';

export default class Form extends Element {
  /**
   * Represents a JSON value.
   * @typedef {(string | number | boolean | null | JSONArray | JSONObject)} JSON
   */

/**
 * Represents a JSON array.
 * @typedef {Array<JSON>} JSONArray
 */

/**
 * Represents a JSON object.
 * @typedef {{[key: string]: JSON}} JSONObject
 */

/**
 * @typedef {object} FormioHooks
 * @property {Function} [beforeSubmit] - Called before a submission is made.
 * @property {Function} [beforeCancel] - Called before a cancel is made.
 * @property {Function} [beforeNext] - Called before the next page is navigated to.
 * @property {Function} [beforePrev] - Called before the previous page is navigated to.
 * @property {Function} [attachComponent] - Called when a component is attached.
 * @property {Function} [setDataValue] - Called when a data value is set.
 * @property {Function} [addComponents] - Called when components are added.
 * @property {Function} [addComponent] - Called when a component is added.
 * @property {Function} [customValidation] - Called when a custom validation is made.
 * @property {Function} [attachWebform] - Called when a webform is attached.
 */

/**
 * @typedef {object} SanitizeConfig
 * @property {string[]} [addAttr] - The html attributes to allow with sanitization.
 * @property {string[]} [addTags] - The html tags to allow with sanitization.
 * @property {string[]} [allowedAttrs] - The html attributes to allow with sanitization.
 * @property {string[]} [allowedTags] - The html tags to allow with sanitization.
 * @property {string[]} [allowedUriRegex] - The regex for allowed URIs.
 * @property {string[]} [addUriSafeAttr] - The URI attributes to allow with sanitization.
 */

/**
 * @typedef {object} ButtonSettings
 * @property {boolean} [showPrevious] - Show the previous button in wizard forms.
 * @property {boolean} [showNext] - Show the next button in wizard forms.
 * @property {boolean} [showCancel] - Show the cancel button in wizard forms.
 * @property {boolean} [showSubmit] - Show the submit button in wizard forms.
 */

/**
 * @typedef {object} FormOptions
 * @property {boolean} [saveDraft] - Enable the save draft feature.
 * @property {number} [saveDraftThrottle] - The throttle for the save draft feature.
 * @property {boolean} [readOnly] - Set this form to readOnly.
 * @property {boolean} [noAlerts] - Disable the alerts dialog.
 * @property {{[key: string]: string}} [i18n] - The translation file for this rendering.
 * @property {string} [template] - Custom logic for creation of elements.
 * @property {boolean} [noDefaults] - Exclude default values from the settings.
 * @property {any} [fileService] - The file service for this form.
 * @property {EventEmitter} [events] - The EventEmitter for this form.
 * @property {string} [language] - The language to render this form in.
 * @property {{[key: string]: string}} [i18next] - The i18next configuration for this form.
 * @property {boolean} [viewAsHtml] - View the form as raw HTML.
 * @property {'form' | 'html' | 'flat' | 'builder' | 'pdf'} [renderMode] - The render mode for this form.
 * @property {boolean} [highlightErrors] - Highlight any errors on the form.
 * @property {string} [componentErrorClass] - The error class for components.
 * @property {any} [templates] - The templates for this form.
 * @property {string} [iconset] - The iconset for this form.
 * @property {import('@formio/core').Component[]} [components] - The components for this form.
 * @property {{[key: string]: boolean}} [disabled] - Disabled components for this form.
 * @property {boolean} [showHiddenFields] - Show hidden fields.
 * @property {{[key: string]: boolean}} [hide] - Hidden components for this form.
 * @property {{[key: string]: boolean}} [show] - Components to show for this form.
 * @property {Formio} [formio] - The Formio instance for this form.
 * @property {string} [decimalSeparator] - The decimal separator for this form.
 * @property {string} [thousandsSeparator] - The thousands separator for this form.
 * @property {FormioHooks} [hooks] - The hooks for this form.
 * @property {boolean} [alwaysDirty] - Always be dirty.
 * @property {boolean} [skipDraftRestore] - Skip restoring a draft.
 * @property {'form' | 'wizard' | 'pdf'} [display] - The display for this form.
 * @property {string} [cdnUrl] - The CDN url for this form.
 * @property {boolean} [flatten] - Flatten the form.
 * @property {boolean} [sanitize] - Sanitize the form.
 * @property {SanitizeConfig} [sanitizeConfig] - The sanitize configuration for this form.
 * @property {ButtonSettings} [buttonSettings] - The button settings for this form.
 * @property {object} [breadcrumbSettings] - The breadcrumb settings for this form.
 * @property {boolean} [allowPrevious] - Allow the previous button (for Wizard forms).
 * @property {string[]} [wizardButtonOrder] - The order of the buttons (for Wizard forms).
