  get itemsLoaded() {
    return this._itemsLoaded || Promise.resolve();
  }

  set itemsLoaded(promise) {
    this._itemsLoaded = promise;
  }

  handleLoadingError(err) {
    this.loading = false;
    if (err.networkError) {
      this.networkError = true;
