          this.setItems(this.downloadedResources);
        }
        break;
      }
      case 'url': {
        if (!forceUpdate && !this.active && !this.calculatedValue && this.component.type === 'select') {
          // If we are lazyLoading, wait until activated.
          this.itemsLoadedResolve();
          return;
        }
